import kotlin.math.abs

fun main() {
    val x = readln().toLong()
    // Camera rotation x: positive = clockwise.
    // Image rotation is opposite: -x.
    // We apply k * 90 clockwise turns (k in 0..3).
    // Total image rotation: -x + 90k.
    // Deviation from vertical = min( (-x + 90k) mod 360, 360 - that ).
    // We want to minimize deviation, and among those minimize k.

    val base = ((-x % 360) + 360) % 360 // value in [0, 359]

    var bestDev = Long.MAX_VALUE
    var bestK = 0

    for (k in 0..3) {
        val angle = (base + 90 * k) % 360
        val dev = minOf(angle, 360 - angle)
        if (dev < bestDev) {
            bestDev = dev
            bestK = k
        }
    }

    println(bestK)
}
